-- ============================================
-- LUMA — Thème 10 : 3e scénario COURT x4 — Une déduction rapide
-- ============================================


update scenarios set content = '{"characters": {"partner": "votre collègue"}, "start_node": "n1", "nodes": {"n1": {"speaker": "partner", "text": "Okay, we''ve got the footprint, the broken window, and the missing jewelry box. Thoughts?", "text_fr": "OK, on a l''empreinte, la fenêtre cassée, et la boîte à bijoux manquante. Des idées ?", "choices": [{"text": "The footprint size suggests someone lighter — maybe not a typical burglar.", "text_fr": "La taille de l''empreinte suggère quelqu''un de plus léger — peut-être pas un cambrioleur typique.", "next": "n2"}, {"text": "Whoever did this knew exactly where the jewelry box was kept.", "text_fr": "Celui qui a fait ça savait exactement où était gardée la boîte à bijoux.", "next": "n2b"}]}, "n2": {"speaker": "partner", "text": "That''s a good observation. What does that tell you?", "text_fr": "C''est une bonne observation. Qu''est-ce que ça vous dit ?", "choices": [{"text": "It might not be a professional thief — maybe someone with inside knowledge.", "text_fr": "Ce n''est peut-être pas un voleur professionnel — peut-être quelqu''un avec des connaissances internes.", "next": "n3"}]}, "n2b": {"speaker": "partner", "text": "Exactly what I was thinking. This wasn''t a random burglary.", "text_fr": "Exactement ce que je pensais. Ce n''était pas un cambriolage au hasard.", "choices": [{"text": "Someone who''s been inside this house before, most likely.", "text_fr": "Quelqu''un qui a déjà été à l''intérieur de cette maison, très probablement.", "next": "n3"}]}, "n3": {"speaker": "partner", "text": "So we''re looking at someone with prior access. A cleaner, a friend, family maybe?", "text_fr": "Donc on cherche quelqu''un avec un accès préalable. Un employé de ménage, un ami, la famille peut-être ?", "choices": [{"text": "We should start by checking who had access to this house recently.", "text_fr": "On devrait commencer par vérifier qui a eu accès à cette maison récemment.", "next": "n4"}, {"text": "Let''s ask the homeowner directly who knew about the jewelry box''s location.", "text_fr": "Demandons directement au propriétaire qui connaissait l''emplacement de la boîte à bijoux.", "next": "n4"}]}, "n4": {"speaker": "partner", "text": "Good plan. This is shaping up to be an inside job, not a random break-in.", "text_fr": "Bon plan. Ça ressemble de plus en plus à un coup monté de l''intérieur, pas un cambriolage au hasard.", "choices": [{"text": "Let''s follow this lead and see where it takes us.", "text_fr": "Suivons cette piste et voyons où elle nous mène.", "next": "end_deduced"}]}, "end_deduced": {"speaker": "partner", "text": "Sharp thinking. This deduction just narrowed our suspect list significantly.", "text_fr": "Raisonnement affûté. Cette déduction vient de réduire considérablement notre liste de suspects.", "end": true, "ending_label": "Déduction rapide et pertinente 🧠🔍"}}}'::jsonb, is_playable = true
where title = 'Une déduction rapide'
  and theme_id = (select id from scenario_themes where position = 10 and language_id = (select id from languages where code = 'en'));
